package br.com.cuidaplus.api.service_request;
import br.com.cuidaplus.api.security.AuthenticatedUser; import br.com.cuidaplus.api.service_request.dto.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/caregiver/service-requests") public class CaregiverServiceRequestController{private final CaregiverServiceRequestService service;public CaregiverServiceRequestController(CaregiverServiceRequestService s){service=s;}@GetMapping public CaregiverServiceRequestPageResponse list(@RequestParam(required=false)ServiceRequestStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return service.list(AuthenticatedUser.id(),status,page,size);}@GetMapping("/{id}")public CaregiverReceivedRequestResponse details(@PathVariable UUID id){return service.details(AuthenticatedUser.id(),id);}@PostMapping("/{id}/accept")public CaregiverReceivedRequestResponse accept(@PathVariable UUID id){return service.accept(AuthenticatedUser.id(),id);}@PostMapping("/{id}/reject")public CaregiverReceivedRequestResponse reject(@PathVariable UUID id,@Valid @RequestBody RejectServiceRequestRequest body){return service.reject(AuthenticatedUser.id(),id,body.reason());}}
